const server=http.createServer(async(req,res)=>{try{let u=new URL(req.url,'http://localhost');if(u.pathname.startsWith('/api/')){let b={};if(req.method==='POST'){let s='';for await(let chunk of req){s+=chunk;if(s.length>16000)fail('Слишком большой запрос')}b=JSON.parse(s||'{}')}let r=rooms.get((b.code||u.searchParams.get('code')||'').toUpperCase()),token=b.token||u.searchParams.get('token');let out;if(u.pathname==='/api/create'){let code;do{code=crypto.randomBytes(3).toString('hex').toUpperCase()}while(rooms.has(code));r={code,players:[],phase:'lobby',chat:[],sliva:[0,0],level:0,levels:[0,0],hanging:['0','0'],wins:[0,0],medals:[0,0],champions:[0,0]};rooms.set(code,r)}if(!r)fail('Комната не найдена');if(['/api/create','/api/join'].includes(u.pathname)){if(r.phase!=='lobby'||r.players.length>=4)fail('Комната закрыта или заполнена');let side=chooseSide(r,b.team);token=crypto.randomBytes(24).toString('hex');r.players.push({side,host:r.players.length===0,name:String(b.name||'Игрок').slice(0,24),token,avatar:String(Number.isInteger(Number(b.avatar))&&Number(b.avatar)>=0&&Number(b.avatar)<200?Number(b.avatar):0)});out={code:r.code,token};if(u.pathname==='/api/create'&&b.solo)fillBots(r,'split')}else{let i=r.players.findIndex(p=>p.token===token);if(i<0)fail('Нет доступа');if(u.pathname==='/api/voice'){if(req.method!=='POST')fail('Требуется POST');const result=voiceApi(r,i,b);res.setHeader('Content-Type','application/json');res.setHeader('Cache-Control','no-store');res.end(JSON.stringify(result));return}if(u.pathname==='/api/pause'){if(!['manual','replay'].includes(b.kind)||typeof b.on!=='boolean')fail('Неверная команда паузы');setPause(r,i,b.kind,b.on)}else if(u.pathname!=='/api/replay')tick(r);if(u.pathname==='/api/replay'){if(!canReplay(r))fail('Повтор доступен при двух и более ботах');if(r.phase==='play')setPause(r,i,'replay',true);else if(r.phase!=='end')fail('Партия не начата')}if(u.pathname==='/api/action'){action(r,i,b);r.deadline=Date.now()+45000;r.botAt=Date.now()+1100;if(b.type==='start')r.pogony=null}if(u.pathname==='/api/chat'){let msg=String(b.message||'').trim().slice(0,300);if(!msg)fail('Пустое сообщение');let now=Date.now();if(now-(r.players[i].lastChat||0)<750)fail('Слишком часто');r.players[i].lastChat=now;r.chat.push({id:crypto.randomUUID(),name:r.players[i].name,message:msg});r.chat=r.chat.slice(-60)}i=r.players.findIndex(p=>p.token===token);out=view(r,i);if(u.pathname==='/api/replay')out.history=r.history||[]}res.setHeader('Content-Type','application/json');res.setHeader('Cache-Control','no-store');res.end(JSON.stringify(out));return}let f=u.pathname==='/'?'index.html':u.pathname.slice(1);if(!['index.html','manifest.json'].includes(f)){res.writeHead(404);res.end();return}res.setHeader('Content-Type',f.endsWith('html')?'text/html; charset=utf-8':'application/manifest+json');res.end(Buffer.from(ASSETS[f],'base64'))}catch(e){res.writeHead(400,{'Content-Type':'application/json; charset=utf-8'});res.end(JSON.stringify({error:e.message}))}});server.listen(process.env.PORT||3000,'0.0.0.0');
